package com.xiaoxiao.pet;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.provider.Settings;import android.view.*;import android.widget.*;

public class MainActivity extends Activity {
 static boolean active;LinearLayout content;final Handler handler=new Handler(Looper.getMainLooper());
 public void onCreate(Bundle b){Data.init(this);Apple.load();setTheme(Apple.dark?com.dafeiyu.companion.R.style.AppThemeDark:com.dafeiyu.companion.R.style.AppTheme);super.onCreate(b);try{if(!PersonaManager.ensureInitialized("main"))handler.post(()->PersonaPanel.show(this,"main"));}catch(Exception e){AgentPanel.fail(this,e);}render();}
 public void onResume(){super.onResume();active=true;AgentRuntime.interruptProactive();Apple.load();render();PermissionsPanel.refresh();if(PetService.instance!=null)PetService.instance.control(true);}
 public void onPause(){active=false;if(PetService.instance!=null)PetService.instance.control(false);super.onPause();}
 public void onDestroy(){DialogLifecycle.close(this);handler.removeCallbacksAndMessages(null);super.onDestroy();}
 public void onConfigurationChanged(android.content.res.Configuration c){super.onConfigurationChanged(c);Apple.load();render();}
 int dp(int v){return Apple.dp(this,v);}TextView text(String s,int size){return Apple.label(this,s,size,false);}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 Button button(LinearLayout parent,String label,View.OnClickListener click){Button b=new Button(this);b.setText(label);Apple.button(b,false);b.setOnClickListener(click);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(50));p.topMargin=dp(8);parent.addView(b,p);return b;}
 LinearLayout panel(){LinearLayout box=column();box.setPadding(dp(18),dp(18),dp(18),dp(18));box.setBackground(Apple.shape(this,Apple.PANEL,24));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(16);content.addView(box,p);return box;}
 void render(){
  Apple.load();getWindow().setStatusBarColor(Apple.BACK);getWindow().setNavigationBarColor(Apple.BACK);getWindow().getDecorView().setSystemUiVisibility(Apple.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  ScrollView scroll=new SpringScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Apple.BACK);content=column();content.setPadding(dp(22),dp(22),dp(22),dp(28));scroll.addView(content);setContentView(scroll);
  TextView eyebrow=text("一只鲸鱼，住进日常",13);eyebrow.setTextColor(Apple.BLUE);content.addView(eyebrow);TextView title=Apple.label(this,"大肥鱼",34,true);title.setPadding(0,dp(8),0,0);content.addView(title);TextView sub=text("有话就说，没话也陪着。",15);sub.setTextColor(Apple.SECONDARY);sub.setPadding(0,dp(6),0,0);content.addView(sub);
  LinearLayout hero=panel();GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,Apple.dark?new int[]{0xff183248,0xff202c3d}:new int[]{0xffe2f2ff,0xfff1f8ff});bg.setCornerRadius(dp(24));hero.setBackground(bg);TextView mood=text("●  "+AgentRuntime.moodLabel(),13);mood.setTextColor(Apple.BLUE);hero.addView(mood);
  ImageView portrait=new ImageView(this);portrait.setContentDescription("蓝色鲸鱼娘大肥鱼");portrait.setScaleType(ImageView.ScaleType.FIT_CENTER);try{portrait.setImageBitmap(BitmapFactory.decodeStream(getAssets().open(Data.role("main").optString("portrait"))));}catch(Exception ignored){}hero.addView(portrait,new LinearLayout.LayoutParams(-1,dp(170)));
  TextView line=Apple.label(this,"我在呢。\n有话就慢慢说。",18,true);line.setGravity(Gravity.CENTER);line.setLineSpacing(dp(4),1);hero.addView(line);Button chat=button(hero,"和她聊聊",v->openChat());Apple.button(chat,true);
  boolean visible=PetService.instance!=null&&PetService.instance.pets.get("main")!=null&&PetService.instance.pets.get("main").visible;
  button(hero,visible?"收起桌宠":"让她住到屏幕上",v->{send(visible?"hideAll":"show","main");handler.postDelayed(this::render,300);});
  if(!Settings.canDrawOverlays(this))content.addView(PermissionsPanel.hint(this));
  LinearLayout connection=panel();connection.addView(Apple.label(this,AgentRuntime.configured()?"模型已配置":"先接通她的声音",18,true));TextView hint=text(AgentRuntime.configured()?"聊天内容会发往你设置的模型服务商。":"填写你自己的模型接口和 Key，就能开始 AI 对话。",13);hint.setTextColor(Apple.SECONDARY);hint.setPadding(0,dp(8),0,dp(4));connection.addView(hint);button(connection,"模型连接",v->Chat.settings(this));
  LinearLayout life=panel();life.addView(Apple.label(this,"我们的日常",18,true));button(life,"记忆手账",v->AgentPanel.memories(this));button(life,PersonaManager.isInitialized("main")?"她的性格 · "+PersonaManager.label("main"):"初次相遇 · 确定性格",v->PersonaPanel.show(this,"main"));button(life,"名字与称呼",v->ProfilePage.show(this,"main"));button(life,"陪伴设置",v->AgentPanel.settings(this));button(life,"动作和大小",v->manage());
  TextView footer=text("独立安卓 AI 桌宠 · 体验版 0.2.0\n非官方社区二创 · 本地保存记忆",12);footer.setTextColor(Apple.SECONDARY);footer.setGravity(Gravity.CENTER);footer.setPadding(0,dp(26),0,0);content.addView(footer);button(content,"关于与开源来源",v->about());
 }
 void openChat(){try{if(!PersonaManager.ensureInitialized("main")){PersonaPanel.show(this,"main");return;}Chat.show(this,"main","main");}catch(Exception e){AgentPanel.fail(this,e);}}
 void send(String action,String role){if(!Settings.canDrawOverlays(this)){PermissionsPanel.show(this);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);startForegroundService(new Intent(this,PetService.class).setAction(action).putExtra("role",role));}
 void size(PetService.Pet p){SizePanel.show(this,p);}
 void manage(){if(!Settings.canDrawOverlays(this)){PermissionsPanel.show(this);return;}send("ensure","main");handler.postDelayed(()->{if(isFinishing()||PetService.instance==null)return;PetService.Pet p=PetService.instance.pets.get("main");if(p==null)return;LinearLayout l=column();l.setPadding(dp(16),0,dp(16),dp(16));button(l,"播放一个动作",v->{if(!p.visible)PetService.instance.show("main");new ActionSheet(this,p,false,null).show();});button(l,"调整大小",v->size(p));GroupedList.toggle(l,"自由播放小动作",p.rotation,(v,on)->{p.rotation=on;if(PetService.instance!=null)PetService.instance.save();});GroupedList.toggle(l,"拖动与弹跳",Data.prefs().getBoolean("physics",true),(v,on)->Data.prefs().edit().putBoolean("physics",on).apply());new Apple.Builder(this).setTitle("她的小动作").setView(l).setPositiveButton("完成",null).show();},250);}
 void about(){new Apple.Builder(this).setTitle("大肥鱼 · 独立陪伴版").setMessage("体验版 0.2.0\n\n基于 yshuang722-spec/xiaoxiao-zhuochong 安卓版改造。桌宠上游：PC2005-cloud/dsh-pet；透明视频路线参考 OTFiles/dsh-pet-inAndroid。人格改编自 ERUIHNIYHBKBNF/dafeiyu-persona。\n\n新增独立对话运行时、可追溯记忆、流式回复、情绪动作与可选主动陪伴。无需 DSH 或电脑常开。\n\n代码按 MIT 条款；动画和角色素材另受上游非商业与署名条款约束。此体验包供非商业体验。\n\n模型提供 AI 回复，动画表达为角色演绎。应用不读取其他 App、屏幕或通知。完整来源和许可随源码包提供。").setPositiveButton("知道了",null).show();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==42&&result==RESULT_OK&&data!=null)try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(AgentRuntime.store().snapshot().toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"手账已导出（不含 API Key）",0).show();}catch(Exception e){Toast.makeText(this,"导出失败",0).show();}}
}
